const presetTokens={scientific_premium:{'palette.ink':'#153746','palette.paper':'#F1F7F8','palette.teal':'#2BB7B0','palette.coral':'#F07858','palette.metal':'#9FBAC0'},educational_cartoon_premium:{'palette.ink':'#243456','palette.paper':'#FFF8E8','palette.teal':'#27B8A8','palette.coral':'#FA765D','palette.metal':'#7784D8'}};
